    "subject": {
      "type": "成年女性",
      "wardrobe": "白色修身背心 / 露肩上衣 + 低腰蓝色牛仔裤，无标志",
      "hair": "深色长发，松散飘动，被风吹拂",
      "makeup": "极简自然妆容",
      "anatomy_rules": "自然身体比例，逼真的手部，无扭曲肢体"
    },
    "panel_direction": {
      "global_rule": "所有 9 个面板均保持相同的身份和造型；改变裁剪和姿势；允许轻微运动模糊和不完美的构图",
      "panel_01": "上半身，头部转动，头发飞扬，柔和模糊",
      "panel_02": "全身侧视图，行走/转身，牛仔裤可见",
      "panel_03": "紧密裁剪肩部/颈部，头发遮住部分脸部",
      "panel_04": "倾斜特写，眼睛半闭，梦幻般的运动感",
      "panel_05": "中景，颈部后仰，手放在锁骨上，头发飞舞",
      "panel_06": "中景至全身，手臂抬起，躯干扭动，抓拍的活力感",
      "panel_07": "紧密裁剪胸部/手部，手放在胸前，柔和模糊",
      "panel_08": "背部中景至全身，一只手臂抬起，头发飘起，牛仔裤腰带可见",
